import Carbon
import XCTest

/// Tasks 7.3 and 7.4: mutating stages stay disabled, controls carry accessibility labels,
/// keyboard navigation works, cancellation stops a running stage without marking it complete,
/// unsupported input is explained in words, and failures are structured messages.
///
/// Fixture backups are generated by `scripts/ui-test.sh` into
/// `~/Library/Caches/Reline/ui-fixtures/{normal,wal}` (password `fixture-password`).
/// Tests that need them skip when the directory is absent.
final class RelineUITests: XCTestCase {
    private var app: XCUIApplication!
    private let fixturePassword = "fixture-password"
    private var previousInputSource: TISInputSource?

    override func setUpWithError() throws {
        continueAfterFailure = false
        app = XCUIApplication()
        selectASCIIInputSource()
    }

    override func tearDownWithError() throws {
        if let prev = previousInputSource { TISSelectInputSource(prev) }
        previousInputSource = nil
    }

    /// Synthesized key events go through the active input method; with Zhuyin, Kotoeri or any
    /// other composing IME selected they never reach the field and XCTest times out. Switch to an
    /// ASCII keyboard layout for the test and restore the user's choice afterwards.
    private func selectASCIIInputSource() {
        guard let current = TISCopyCurrentKeyboardInputSource()?.takeRetainedValue() else { return }
        if let ascii = TISGetInputSourceProperty(current, kTISPropertyInputSourceIsASCIICapable),
           Unmanaged<CFBoolean>.fromOpaque(ascii).takeUnretainedValue() == kCFBooleanTrue,
           let type = TISGetInputSourceProperty(current, kTISPropertyInputSourceType),
           Unmanaged<CFString>.fromOpaque(type).takeUnretainedValue() as String == kTISTypeKeyboardLayout as String {
            return
        }
        previousInputSource = current
        let filter = [kTISPropertyInputSourceID as String: "com.apple.keylayout.ABC"] as CFDictionary
        guard let list = TISCreateInputSourceList(filter, true)?.takeRetainedValue() as? [TISInputSource],
              let abc = list.first else { return }
        TISEnableInputSource(abc)
        TISSelectInputSource(abc)
        RunLoop.current.run(until: Date().addingTimeInterval(0.5))
    }

    // MARK: Helpers

    /// Tests assert English labels, so the app is pinned to English regardless of the machine's
    /// language or the user's stored in-app choice (`-ui.language system` overrides the default
    /// domain; `-AppleLanguages (en)` makes "system" resolve to English).
    /// `-ApplePersistenceIgnoreState YES` skips window restoration (a stale saved state can restore
    /// zero windows) and `-NSTreatUnknownArgumentsAsOpen NO` stops AppKit from reading the
    /// `--ui-test-folders key=path` pairs as documents to open, which would suppress the default window.
    private func launch(folders: [String: String] = [:], extraArguments: [String] = [], language: String = "en") {
        var args = ["-ApplePersistenceIgnoreState", "YES", "-NSTreatUnknownArgumentsAsOpen", "NO",
                    "-AppleLanguages", "(\(language))", "-ui.language", "system"] + extraArguments
        if !folders.isEmpty {
            args += ["--ui-test-folders"] + folders.map { "\($0.key)=\($0.value)" }
        }
        app.launchArguments = args
        app.launch()
        app.activate()
        XCTAssertTrue(app.windows.firstMatch.waitForExistence(timeout: 10))
    }

    /// Stage rows are single accessibility elements labelled "<Title>, <state>" and identified
    /// as `stage-<id>`, so VoiceOver reads the state and tests address the row regardless of it.
    private func stageRow(_ id: String) -> XCUIElement {
        app.descendants(matching: .any).matching(identifier: "stage-\(id)").firstMatch
    }

    private func selectStage(_ id: String) {
        let row = stageRow(id)
        XCTAssertTrue(row.waitForExistence(timeout: 5), "stage row \(id)")
        row.click()
    }

    /// macOS exposes a combined SwiftUI text element's content as `value` (label stays empty).
    private func text(of element: XCUIElement) -> String {
        [element.label, (element.value as? String) ?? ""].first { !$0.isEmpty } ?? ""
    }

    private func stageLabel(_ id: String) -> String { text(of: stageRow(id)) }

    /// SwiftUI `.alert` is a window-modal sheet on macOS.
    private var errorAlert: XCUIElement {
        app.sheets.firstMatch.exists ? app.sheets.firstMatch : app.dialogs.firstMatch
    }

    private var errorAlertPresent: Bool { app.sheets.firstMatch.exists || app.dialogs.firstMatch.exists }

    private func waitForStageLabel(_ id: String, toContain text: String, timeout: TimeInterval) -> Bool {
        let deadline = Date().addingTimeInterval(timeout)
        while Date() < deadline {
            if stageLabel(id).localizedCaseInsensitiveContains(text) { return true }
            RunLoop.current.run(until: Date().addingTimeInterval(0.5))
        }
        return false
    }

    private func makeTempDirs(_ names: [String]) throws -> [String: URL] {
        let tmp = FileManager.default.temporaryDirectory.appendingPathComponent("ui-\(UUID().uuidString)")
        var out: [String: URL] = [:]
        for n in names {
            let u = tmp.appendingPathComponent(n)
            try FileManager.default.createDirectory(at: u, withIntermediateDirectories: true)
            out[n] = u
        }
        return out
    }

    private struct Fixture { let old: String; let current: String }

    private func fixture(_ name: String) throws -> Fixture {
        let base = FileManager.default.homeDirectoryForCurrentUser
            .appendingPathComponent("Library/Caches/Reline/ui-fixtures/\(name)/expected.json")
        guard let data = try? Data(contentsOf: base),
              let obj = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
              let old = obj["old_backup_dir"] as? String, let cur = obj["current_backup_dir"] as? String
        else { throw XCTSkip("fixture \(name) not generated; run scripts/ui-test.sh") }
        return Fixture(old: old, current: cur)
    }

    /// Types the password through the keyboard (the only way a real user enters it) and verifies
    /// the secure field accepted it. Retries because focus may lag the click on a busy machine.
    private func enterPassword(_ password: String) {
        let pw = app.secureTextFields["Encrypted backup password"].firstMatch
        XCTAssertTrue(pw.waitForExistence(timeout: 5))
        for attempt in 1...3 {
            app.activate()
            pw.click()
            pw.typeText(password)
            if !((pw.value as? String) ?? "").isEmpty { return }
            XCTContext.runActivity(named: "password entry attempt \(attempt) did not register") { _ in }
        }
        XCTFail("typed password never reached the secure field")
    }

    /// Blockers for a stage are one combined accessibility element ("<Stage> is blocked: ...").
    private func blockers(_ stage: String) -> XCUIElement {
        app.descendants(matching: .any).matching(identifier: "blockers-\(stage)").firstMatch
    }

    // MARK: Task 7.3 — gating

    func testMutatingStagesAreDisabledOnFreshLaunch() {
        launch()
        selectStage("analysis")
        let analyze = app.buttons["Analyze"].firstMatch
        XCTAssertTrue(analyze.waitForExistence(timeout: 5))
        XCTAssertFalse(analyze.isEnabled, "Analyze must be disabled before both intakes")
        selectStage("review")
        XCTAssertFalse(app.buttons["Create patched clone"].firstMatch.exists, "patch button must not appear without a plan")
        selectStage("export")
        let export = app.buttons["Export verified backup and reports"].firstMatch
        XCTAssertTrue(export.waitForExistence(timeout: 5))
        XCTAssertFalse(export.isEnabled, "Export must be disabled before verification")
        // Blockers are explained in words, not just greyed out.
        XCTAssertTrue(blockers("export").waitForExistence(timeout: 5))
        XCTAssertTrue(text(of: blockers("export")).contains("The clone has not passed verification."), text(of: blockers("export")))
    }

    // MARK: Task 7.4 — VoiceOver labels

    func testStageRowsExposeAccessibilityLabelsWithState() {
        launch()
        for (id, title) in [("intake", "Intake"), ("analysis", "Analysis"), ("review", "Review"),
                            ("patching", "Patching"), ("verification", "Verification"), ("export", "Export")] {
            XCTAssertTrue(stageRow(id).waitForExistence(timeout: 5), id)
            let label = stageLabel(id)
            XCTAssertTrue(label.hasPrefix("\(title), "), "row label carries the state: \(label)")
        }
        XCTAssertTrue(stageLabel("patching").contains("mutating stage"), "mutating stages are announced")
        XCTAssertTrue(stageLabel("export").contains("mutating stage"))
        selectStage("intake")
        XCTAssertTrue(app.secureTextFields["Encrypted backup password"].firstMatch.waitForExistence(timeout: 5))
        for label in ["Choose Session workspace", "Choose Old iPhone backup (copy)", "Choose Current iPhone backup (copy)"] {
            XCTAssertTrue(app.buttons[label].firstMatch.exists, label)
        }
        XCTAssertTrue(app.checkBoxes.firstMatch.exists, "remember-password toggle present")
        XCTAssertEqual(app.checkBoxes.firstMatch.value as? Int, 0, "remember password defaults off")
        XCTAssertFalse(app.buttons["Read old backup"].firstMatch.isEnabled, "disabled without folders and password")
    }

    // MARK: Localization — Traditional Chinese

    /// With the system language set to Traditional Chinese the whole shell, including stage rows,
    /// buttons, blockers and the error alert, is presented in zh-Hant; identifiers stay stable.
    func testTraditionalChineseLocalization() throws {
        let dirs = try makeTempDirs(["ws", "not-a-backup"])
        launch(folders: ["workspace": dirs["ws"]!.path, "current": dirs["not-a-backup"]!.path], language: "zh-Hant")
        XCTAssertTrue(stageRow("intake").waitForExistence(timeout: 5))
        XCTAssertTrue(stageLabel("intake").hasPrefix("讀取備份, "), stageLabel("intake"))
        XCTAssertTrue(stageLabel("patching").contains("會寫入檔案的階段"), stageLabel("patching"))
        selectStage("export")
        XCTAssertTrue(app.buttons["匯出已驗證的備份與報告"].firstMatch.waitForExistence(timeout: 5))
        XCTAssertTrue(text(of: blockers("export")).contains("副本尚未通過驗證。"), text(of: blockers("export")))
        selectStage("intake")
        let pw = app.secureTextFields["加密備份密碼"].firstMatch
        XCTAssertTrue(pw.waitForExistence(timeout: 5), "password field carries the Chinese label")
        app.activate(); pw.click(); pw.typeText("whatever")
        let read = app.buttons["讀取新機備份"].firstMatch
        XCTAssertTrue(read.waitForExistence(timeout: 5))
        read.click()
        XCTAssertTrue(app.sheets.firstMatch.waitForExistence(timeout: 15) || app.dialogs.firstMatch.waitForExistence(timeout: 1))
        let body = errorAlert.staticTexts.allElementsBoundByIndex.map { text(of: $0) }.joined(separator: "\n")
        XCTAssertTrue(body.contains("不是 Finder 備份"), body)
        XCTAssertTrue(body.contains("錯誤代碼：invalid_backup_structure"), body)
        XCTAssertTrue(body.contains("怎麼做："), "localized remedy label: \(body)")
        XCTAssertFalse(body.contains("whatever"))
        errorAlert.buttons["好"].firstMatch.click()
    }

    /// The language picker in the window toolbar switches the interface immediately, without a
    /// relaunch; the choice is stored (tests launch with `-ui.language system`, so they are not
    /// affected by what a user picked).
    func testLanguagePickerSwitchesLiveAndBack() {
        launch()
        XCTAssertTrue(app.buttons["Read old backup"].firstMatch.waitForExistence(timeout: 5))
        let picker = app.descendants(matching: .any).matching(identifier: "language-picker").firstMatch
        XCTAssertTrue(picker.waitForExistence(timeout: 5), "language picker in the toolbar")
        picker.click()
        let zh = app.menuItems["繁體中文"].firstMatch
        XCTAssertTrue(zh.waitForExistence(timeout: 3))
        zh.click()
        XCTAssertTrue(app.buttons["讀取舊機備份"].firstMatch.waitForExistence(timeout: 5), "buttons re-render in Chinese")
        XCTAssertTrue(stageLabel("intake").hasPrefix("讀取備份, "), stageLabel("intake"))
        XCTAssertEqual(text(of: picker), "語言", "the picker's own label is translated")
        picker.click()
        let en = app.menuItems["English"].firstMatch
        XCTAssertTrue(en.waitForExistence(timeout: 3))
        en.click()
        XCTAssertTrue(app.buttons["Read old backup"].firstMatch.waitForExistence(timeout: 5), "back to English")
        picker.click()
        let system = app.menuItems["System language"].firstMatch
        XCTAssertTrue(system.waitForExistence(timeout: 3))
        system.click()
        XCTAssertTrue(app.buttons["Read old backup"].firstMatch.waitForExistence(timeout: 5))
    }

    // MARK: Task 7.4 — keyboard navigation

    func testKeyboardNavigationAndCancelCommandWhenIdle() {
        launch()
        selectStage("intake")
        enterPassword("typed-by-keyboard")
        // Escape must not crash or clear state; the Cancel command is disabled while idle.
        app.typeKey(.escape, modifierFlags: [])
        XCTAssertFalse(((app.secureTextFields["Encrypted backup password"].firstMatch.value as? String) ?? "").isEmpty)
        let menu = app.menuBars.menuBarItems["View"].firstMatch
        if menu.exists {
            menu.click()
            let cancel = app.menuItems["Cancel Operation"].firstMatch
            if cancel.waitForExistence(timeout: 2) { XCTAssertFalse(cancel.isEnabled) }
            app.typeKey(.escape, modifierFlags: [])
        }
        // Stage list is reachable by keyboard: arrow keys move the selection.
        stageRow("intake").click()
        app.typeKey(.downArrow, modifierFlags: [])
        XCTAssertTrue(app.buttons["Analyze"].firstMatch.waitForExistence(timeout: 5), "down arrow selected Analysis")
    }

    // MARK: Task 7.4 — cancellation and progress

    func testCancelDuringIntakeShowsProgressAndLeavesStageUncommitted() throws {
        let fx = try fixture("normal")
        let dirs = try makeTempDirs(["ws"])
        // Each progress callback sleeps 400 ms so Cancel can be clicked while intake is running.
        launch(folders: ["workspace": dirs["ws"]!.path, "old": fx.old], extraArguments: ["--ui-test-progress-delay-ms", "400"])
        selectStage("intake")
        enterPassword(fixturePassword)
        let read = app.buttons["Read old backup"].firstMatch
        XCTAssertTrue(read.isEnabled)
        read.click()

        let progress = app.progressIndicators["operation-progress"].firstMatch
        XCTAssertTrue(progress.waitForExistence(timeout: 10), "progress indicator appears while running")
        XCTAssertTrue(text(of: progress).localizedCaseInsensitiveContains("progress"), "VoiceOver label: \(text(of: progress))")
        let cancel = app.buttons["cancel-operation"].firstMatch
        XCTAssertTrue(cancel.exists && cancel.isEnabled, "Cancel is available while running")
        XCTAssertTrue(waitForStageLabel("intake", toContain: "running", timeout: 10), "stage row announces running")
        cancel.click()

        let notice = app.descendants(matching: .any).matching(identifier: "notice").firstMatch
        XCTAssertTrue(notice.waitForExistence(timeout: 60), "cancellation notice appears")
        XCTAssertTrue(text(of: notice).hasPrefix("Cancelled."), text(of: notice))
        XCTAssertTrue(text(of: notice).contains("not marked complete"), text(of: notice))
        XCTAssertFalse(errorAlertPresent, "cancellation is not presented as an error alert")
        XCTAssertFalse(progress.exists, "progress indicator is gone")
        XCTAssertTrue(waitForStageLabel("intake", toContain: "cancelled", timeout: 10), "stage row shows cancelled: \(stageLabel("intake"))")
        XCTAssertFalse(stageLabel("intake").contains("committed"))
        app.buttons["dismiss-notice"].firstMatch.click()
        XCTAssertFalse(notice.exists)
        selectStage("analysis")
        XCTAssertFalse(app.buttons["Analyze"].firstMatch.isEnabled, "later stages stay disabled after cancellation")
        XCTAssertTrue(text(of: blockers("analysis")).contains("Old backup intake is not complete."), text(of: blockers("analysis")))
    }

    // MARK: Task 7.4 — unsupported input

    func testUnsupportedCurrentBackupIsExplainedAndBlocksPatching() throws {
        let fx = try fixture("wal")
        let dirs = try makeTempDirs(["ws"])
        launch(folders: ["workspace": dirs["ws"]!.path, "current": fx.current])
        selectStage("intake")
        enterPassword(fixturePassword)
        let read = app.buttons["Read current backup"].firstMatch
        XCTAssertTrue(read.isEnabled)
        read.click()
        let unsupported = app.descendants(matching: .any).matching(identifier: "unsupported-current").firstMatch
        XCTAssertTrue(unsupported.waitForExistence(timeout: 90), "unsupported explanation appears after intake")
        let why = text(of: unsupported)
        XCTAssertTrue(why.hasPrefix("Unsupported for patching."), why)
        XCTAssertTrue(why.contains("-wal") && why.contains("replayed"), "names the pending WAL: \(why)")
        XCTAssertTrue(app.staticTexts["No, analysis only"].firstMatch.exists, "patchable row says No")
        XCTAssertFalse(errorAlertPresent, "unsupported input is not an error; intake still succeeded")
        XCTAssertTrue(waitForStageLabel("intake", toContain: "committed", timeout: 10), stageLabel("intake"))
        // The explanation also appears as a blocker on the stage that would mutate.
        selectStage("review")
        XCTAssertTrue(blockers("review").waitForExistence(timeout: 5))
        XCTAssertTrue(text(of: blockers("review")).contains("Analysis has not run."), text(of: blockers("review")))
    }

    // MARK: Task 7.4 — structured failure

    func testStructuredFailureIsPresentedWithCodeAndRemedy() throws {
        let dirs = try makeTempDirs(["ws", "not-a-backup"])
        launch(folders: ["workspace": dirs["ws"]!.path, "current": dirs["not-a-backup"]!.path])
        selectStage("intake")
        enterPassword("whatever")
        let read = app.buttons["Read current backup"].firstMatch
        XCTAssertTrue(read.isEnabled)
        read.click()
        XCTAssertTrue(app.sheets.firstMatch.waitForExistence(timeout: 15) || app.dialogs.firstMatch.waitForExistence(timeout: 1), "an error alert must appear")
        let alert = errorAlert
        let body = alert.staticTexts.allElementsBoundByIndex.map { text(of: $0) }.joined(separator: "\n")
        XCTAssertTrue(body.contains("Not a Finder backup") || body.contains("invalid_backup_structure"), body)
        XCTAssertTrue(body.contains("Code: "), "structured code shown: \(body)")
        XCTAssertTrue(body.contains("What to do: "), "remedy shown: \(body)")
        XCTAssertFalse(body.contains("whatever"), "password must never appear in error text")
        alert.buttons["OK"].firstMatch.click()
        // The stage list reflects the failure without enabling later stages.
        XCTAssertTrue(waitForStageLabel("intake", toContain: "failed", timeout: 10), stageLabel("intake"))
        selectStage("analysis")
        XCTAssertFalse(app.buttons["Analyze"].firstMatch.isEnabled)
    }
}
